const $=s=>document.querySelector(s),sceneElement=$('#scene'),aboutElement=$('#about'),track=$('#scroll-track');
const initial=readRoute(location.href);let lang=initial.lang,scene=initial.scene,progress=0,lastScene='start',routeDepth=0,ready=false,keepsake='snail',sound=false,ambientPaused=matchMedia('(prefers-reduced-motion: reduce)').matches,restoring=false,lastY=0,saveTimer,scrollFrame=0,viewportHeight=innerHeight,renderedScene=null,transferChoice=null,rimProgress=0,ambientTime=0;
let sketchLines=[],sketchActive=false;
const motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const ocean=new Ocean($('#water')),seaSound=new SeaSound(),paintedWater=new PaintedWater($('#ocean'));
const c=()=>CONTENT[lang],escape=s=>String(s??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
