const button=(text,action,kind='primary')=>`<button class="${kind}" data-action="${action}">${escape(text)}${kind==='primary'?arrow:''}</button>`;
const announce=text=>{$('#status').textContent=text;};
const routeState=y=>({coquillages:true,journey:2,depth:routeDepth,y,lastScene});
function storePosition(y=window.scrollY){if(scene!=='about')history.replaceState(routeState(y),'',routeUrl(location.href,scene,lang));}
function applyPreferences(){const t=c(),active=!ambientPaused;document.documentElement.lang=lang;document.body.dataset.motion=active?'on':'off';ocean.setActive(active);paintedWater.setActive(active);$('#motion').setAttribute('aria-label',t.controls[active?'movement-off':'movement-on']);$('#motion').setAttribute('aria-pressed',String(!active));$('#sound').setAttribute('aria-label',t.controls[sound?'sound-off':'sound-on']);$('#sound').setAttribute('aria-pressed',String(sound));$('#fullscreen').setAttribute('aria-label',t.controls.fullscreen);$('#back span').textContent=t.controls.back;$('#home').textContent=t.controls.home;$('#advance').textContent=t.controls.next;$('#advance').hidden=scene==='start'||scene==='ending'||scene==='about';$('.languages').setAttribute('aria-label',t.controls.language);$('#progress').setAttribute('aria-label',t.controls.progress);document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.lang===lang)));}
function updateTrack(){viewportHeight=innerHeight;track.style.height=journeyHeight(viewportHeight)+'px';}
function go(id,{at=0,replace=false}={}){
  clearTimeout(saveTimer);if(scene!=='about'){lastScene=scene;storePosition();}
  const y=id==='about'?lastY:offsetFor(id,at,viewportHeight);scene=id;progress=at;
  if(!replace)routeDepth++;
  history[replace?'replaceState':'pushState'](routeState(y),'',routeUrl(location.href,id,lang));
  restoring=true;if(id!=='about'){window.scrollTo({top:y,behavior:'instant'});lastY=y;}render(true);requestAnimationFrame(()=>{restoring=false;});
}
function back(){if(routeDepth>0)history.back();else if(scene==='about')go(lastScene,{replace:true});else if(scene!=='start')go(previousScene(scene),{at:.78,replace:true});else location.href='https://salonformat.com';}
window.addEventListener('popstate',()=>{clearTimeout(saveTimer);const route=readRoute(location.href);lang=route.lang;scene=route.scene;routeDepth=history.state?.depth||0;lastScene=history.state?.lastScene||'start';const y=history.state?.journey===2?history.state.y:offsetFor(scene,0,innerHeight);restoring=true;window.scrollTo({top:y,behavior:'instant'});lastY=y;progress=scene==='about'?0:positionAt(y,viewportHeight).progress;render(true);requestAnimationFrame(()=>{restoring=false;});});
history.scrollRestoration='manual';
function syncScroll(){scrollFrame=0;if(restoring||scene==='about')return;const y=window.scrollY,next=positionAt(y,viewportHeight);if(next.scene!==scene){history.replaceState(routeState(lastY),'',routeUrl(location.href,scene,lang));lastScene=scene;scene=next.scene;progress=next.progress;routeDepth++;history.pushState(routeState(y),'',routeUrl(location.href,scene,lang));render(false);}else{progress=next.progress;updateProgress();updateDrawing();}lastY=y;clearTimeout(saveTimer);saveTimer=setTimeout(()=>storePosition(),180);}
window.addEventListener('scroll',()=>{if(!scrollFrame)scrollFrame=requestAnimationFrame(syncScroll);},{passive:true});
$('#back').addEventListener('click',back);$('#home').addEventListener('click',()=>go('start'));$('#advance').addEventListener('click',()=>go(nextScene(scene)));
$('#motion').addEventListener('click',()=>{ambientPaused=!ambientPaused;applyPreferences();});
document.querySelectorAll('[data-lang]').forEach(b=>b.addEventListener('click',()=>{lang=b.dataset.lang;history.replaceState(routeState(lastY),'',routeUrl(location.href,scene,lang));render(false);}));
$('#sound').addEventListener('click',async()=>{try{await seaSound.set(!sound);sound=!sound;applyPreferences();}catch{announce(c().ui.audioUnavailable);}});
$('#fullscreen').addEventListener('click',async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{announce(c().ui.fullscreenUnavailable);}});
window.addEventListener('pointermove',e=>{if(!motion||ambientPaused)return;document.documentElement.style.setProperty('--px',(e.clientX/innerWidth-.5).toFixed(3));document.documentElement.style.setProperty('--py',(e.clientY/innerHeight-.5).toFixed(3));},{passive:true});
async function prepare(id){try{if(id==='animal')await artImage('assets/snail.png').decode();if(id==='edge')await artImage('assets/snail-shell.png').decode();if(id==='transfer')await artImage('assets/scallop.png').decode();if(id==='growth')await readyGrowth('snail');if(id==='bivalve')await readyGrowth('mussel');if(id==='ending')await artImage('assets/scallop.png').decode();if(scene===id){ready=true;sceneElement.dataset.ready='true';updateDrawing();}}catch{if(scene===id){sceneElement.dataset.ready='error';const notice=$('.art-loading');if(notice)notice.textContent=c().journey.loadError;announce(c().journey.loadError);}}}
function render(focus=false){if(renderedScene!==scene){$('#experience').scrollTop=0;renderedScene=scene;}ready=false;sceneElement.dataset.ready='loading';const t=c(),s=t[scene],index=SCENES.indexOf(scene);document.body.dataset.scene=scene;paintedWater.setScene(scene);ocean.setScene(scene);applyPreferences();document.title=(s?.title||t.controls['source-title'])+' — SALONFORMAT';$('#progress').innerHTML=SCENES.map((id,i)=>`<a href="${routeUrl(location.href,id,lang)}" data-scene="${id}" ${id===scene?'aria-current="step"':''} class="${i<index?'done':''}" aria-label="${escape(t.ui.progressNames[i])}"></a>`).join('');if(scene==='about'){sceneElement.hidden=true;aboutElement.hidden=false;$('#journey-hint').hidden=true;renderAbout();return;}sceneElement.hidden=false;aboutElement.hidden=true;let copy='',stage='';const title=`<h1 id="scene-title" tabindex="-1">${escape(scene==='transfer'?t.journey.transferTitle:s.title)}</h1>`;
if(scene==='start'){copy=`${title}<p class="intro-learning">${escape(s.body)}</p><p class="intro-reward">${escape(s.reward)}</p><p class="journey-hint">${escape(t.journey.startHint)}</p><div class="actions">${button(s.action,'begin')}</div>`;}
if(scene==='animal'){copy=`${title}<p id="scene-body"></p>`;stage=`<canvas id="living-snail" class="growth-canvas" role="button" tabindex="0" aria-label="${escape({de:'Die Öffnung des Schneckenhauses ansehen',fr:'Voir l’ouverture de plus près',en:'Look closer at the shell opening'}[lang])}"></canvas>`;}
if(scene==='edge'){copy=`${title}<p id="scene-body"></p>`;stage=`<canvas id="shell-layers" class="growth-canvas" role="img" aria-label="${escape(s.title)}"></canvas>`;}
if(scene==='growth'){copy=`${title}<p id="scene-body"></p><p class="model-note">${escape(s['model-note'])}</p>`;stage=`<canvas id="shell-growth" class="growth-canvas" role="img" aria-label="${escape(s.after)}"></canvas>`;}
if(scene==='bivalve'){copy=`${title}<p id="scene-body"></p><p class="model-note">${escape(t.growth['model-note'])}</p>`;stage=`<canvas id="mussel-growth" class="growth-canvas" role="img" aria-label="${escape(s.after)}"></canvas>`;}
if(scene==='transfer'){copy=`${title}<p>${escape(t.journey.transferBody)}</p><p id="transfer-feedback" class="transfer-feedback" role="status"></p>`;stage=`<img src="assets/scallop.png" alt="${escape(t.journey.transferTitle)}"><canvas id="transfer-growth" class="growth-canvas" aria-hidden="true"></canvas><button class="shell-touch" data-place="hinge" aria-label="${escape(t.journey.hingeLabel)}"></button><button class="shell-touch" data-place="edge" aria-label="${escape(t.journey.edgeLabel)}"></button>`;}
if(scene==='ending'){copy=`${title}<p>${escape(s.body)}</p><p class="sketch-help">${escape(t.sketch.hint)}</p><div class="sketch-tools"><button class="text-button" data-action="clear-sketch">${escape(t.sketch.clear)}</button><button class="text-button" data-action="mark-rim">${escape(t.sketch.mark)}</button></div><p id="sketch-status" role="status"></p><div class="actions">${button(s.download,'download')}${button(s.replay,'restart','secondary')}${button(s.sources,'about','text-button')}</div>`;stage=`<div class="card-preview"><div class="card-title">${escape(s['keepsake-title'])}</div><canvas id="card-drawing" tabindex="0" role="img" aria-label="${escape(t.sketch.hint)}"></canvas><p>${escape(s['card-line-2'])}</p><small>${escape(s['card-note'])}<br>SALONFORMAT</small></div>`;}

sceneElement.className='scene-'+scene;sceneElement.innerHTML=`<div class="scene-copy">${copy}</div><div class="stage" ${scene==='transfer'?`role="group" aria-label="${escape(t.journey.transferTitle)}"`:''}>${stage}<span class="art-loading">${escape(t.controls.loading)}</span></div>`;updateProgress();prepare(scene);if(focus){$('#scene-title').focus({preventScroll:true});$('#experience').scrollTop=0;}}
function updateProgress(){const t=c();sceneElement.dataset.progress=progress.toFixed(4);const text=$('#scene-body');let body='';if(scene==='animal')body=progress<.53?t.animal.body:t.why.body;if(scene==='edge')body=progress<.8?t.edge.body:t.edge.extra;if(scene==='growth')body=progress<.74?t.growth.instruction:t.growth.after;if(scene==='bivalve')body=progress<.72?t.bivalve.body:t.bivalve.after;if(text&&text.textContent!==body)text.textContent=body;const heading=$('#scene-title');if(scene==='animal'&&heading)heading.textContent=progress<.53?t.animal.title:t.why.title;
const hint=$('#journey-hint');hint.hidden=scene==='ending'||scene==='about';hint.textContent=scene==='transfer'&&transferChoice==='edge'?t.journey.doneHint:t.journey[scene+'Hint']||'';if(scene==='start')hint.hidden=true;
let cameraScale=1,cameraY=0,subjectScale=1,subjectY=0;if(motion){if(scene==='start'){cameraScale=1+progress*.18;cameraY=-progress*30;}if(scene==='animal'){cameraScale=1+progress*.08;cameraY=-progress*12;subjectScale=.73+.27*progress;subjectY=(1-progress)*28;}if(scene==='edge')cameraScale=1+progress*.07;}
document.documentElement.style.setProperty('--camera-scale',cameraScale);document.documentElement.style.setProperty('--camera-y',cameraY+'px');document.documentElement.style.setProperty('--subject-scale',subjectScale);document.documentElement.style.setProperty('--subject-y',subjectY+'px');$('#scene-time').style.setProperty('--progress',String((SCENES.indexOf(scene)+progress)/SCENES.length));if(scene==='transfer')updateTransferFeedback();}
function updateTransferFeedback(){const node=$('#transfer-feedback');if(!node)return;const message=transferChoice==='edge'?c().journey.correct:transferChoice==='hinge'?c().journey.wrong:transferChoice==='outside'?c().journey.outsideHint:'';if(node.textContent!==message)node.textContent=message;node.dataset.correct=String(transferChoice==='edge');document.querySelectorAll('[data-place]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.place===transferChoice)));}
function updateDrawing(){if(!ready)return;const layers=$('#shell-layers');if(layers)drawShellLayers(layers,clamp(progress/.85));const shell=$('#shell-growth');if(shell)drawShell(shell,growthAt(progress));const living=$('#living-snail');if(living)drawLivingSnail(living,ambientTime,motion&&!ambientPaused);const mussel=$('#mussel-growth');if(mussel)drawMussel(mussel,growthAt(progress));const transfer=$('#transfer-growth');if(transfer){if(transferChoice==='edge')drawTransfer(transfer,artImage('assets/scallop.png'),rimProgress);else transfer.getContext('2d').clearRect(0,0,transfer.width,transfer.height);placeTargets();}const card=$('#card-drawing');if(card){paintKeepsake(card,artImage('assets/scallop.png'),sketchLines);updateSketchState();}}
function placeTargets(){const stage=$('.scene-transfer .stage'),image=artImage('assets/scallop.png');if(!stage||!image.naturalWidth)return;const w=stage.clientWidth,h=stage.clientHeight,scale=Math.min(w/image.naturalWidth,h/image.naturalHeight),ox=(w-image.naturalWidth*scale)/2,oy=(h-image.naturalHeight*scale)/2;for(const [place,y]of [['hinge',.13],['edge',.91]]){const b=$(`[data-place="${place}"]`);if(b){b.style.left=ox+image.naturalWidth*.5*scale+'px';b.style.top=oy+image.naturalHeight*y*scale+'px';}}}
let transferPixels;
function chooseAt(event){const image=artImage('assets/scallop.png'),box=$('.scene-transfer .stage').getBoundingClientRect(),point=containedImagePoint(event.clientX,event.clientY,box,image.naturalWidth,image.naturalHeight),x=Math.round(point.x),y=Math.round(point.y),w=image.naturalWidth,h=image.naturalHeight;if(!transferPixels){const sample=document.createElement('canvas');sample.width=w;sample.height=h;const ctx=sample.getContext('2d',{willReadFrequently:true});ctx.drawImage(image,0,0);transferPixels=ctx.getImageData(0,0,w,h).data;}if(x<0||x>=w||y<0||y>=h){choose('outside');return;}let bottom=h-1;while(bottom>0&&transferPixels[(bottom*w+x)*4+3]<100)bottom--;if(y>h*.55&&y>=bottom-h*.13&&y<=bottom+h*.035){choose('edge');return;}let alpha=0;for(let dy=-3;dy<=3;dy++)for(let dx=-3;dx<=3;dx++)if(x+dx>=0&&x+dx<w&&y+dy>=0&&y+dy<h)alpha=Math.max(alpha,transferPixels[((y+dy)*w+x+dx)*4+3]);choose(alpha>80?'hinge':'outside');}
function choose(place){transferChoice=place;rimProgress=motion?0:1;updateProgress();updateDrawing();}
let last=performance.now(),lastDraw=0;function tick(now){const dt=Math.max(0,Math.min((now-last)/1000,.1));last=now;if(!document.hidden){if(motion&&!ambientPaused)ambientTime+=dt;const reveal=scene==='transfer'&&transferChoice==='edge'&&rimProgress<1;if(reveal)rimProgress=Math.min(1,rimProgress+dt/1.2);if(ready&&now-lastDraw>30&&((scene==='animal'&&motion&&!ambientPaused)||reveal)){updateDrawing();lastDraw=now;}}requestAnimationFrame(tick);}requestAnimationFrame(tick);
window.addEventListener('resize',()=>{const state=positionAt(window.scrollY,viewportHeight);restoring=true;updateTrack();if(scene!=='about'){const changed=scene!==state.scene;scene=state.scene;progress=state.progress;const y=offsetFor(scene,progress,viewportHeight);window.scrollTo({top:y,behavior:'instant'});lastY=y;if(changed)render(false);else updateProgress();storePosition(y);}updateDrawing();requestAnimationFrame(()=>{restoring=false;});});window.addEventListener('artready',updateDrawing);
document.addEventListener('keydown',event=>{if(event.target.id==='living-snail'&&(event.key==='Enter'||event.key===' ')){event.preventDefault();go('edge');}});
document.addEventListener('click',event=>{const anchor=event.target.closest('a[data-scene]');if(anchor){event.preventDefault();go(anchor.dataset.scene);return;}if(event.target.id==='living-snail'){go('edge');return;}const place=event.target.closest('[data-place]');if(place){choose(place.dataset.place);return;}if(scene==='transfer'&&event.target.closest('.scene-transfer .stage')){chooseAt(event);return;}const keep=event.target.closest('[data-keepsake]');if(keep){keepsake=keep.dataset.keepsake;render(false);return;}const action=event.target.closest('[data-action]')?.dataset.action;if(action==='begin'){readyGrowth('snail').catch(()=>{});readyGrowth('mussel').catch(()=>{});go('animal');}if(action==='take-card')go('ending');if(action==='clear-sketch'){sketchLines=[];updateDrawing();}if(action==='mark-rim'){sketchLines=[suggestedRim(artImage('assets/scallop.png'))];updateDrawing();}if(action==='restart'){transferChoice=null;rimProgress=0;sketchLines=[];go('start');}if(action==='about')go('about');if(action==='close-about')back();if(action==='download')downloadCard();});
function renderAbout(){const t=c();aboutElement.innerHTML=`<h1 id="about-title" tabindex="-1">${escape(t.controls['source-title'])}</h1><p>${escape(t.controls['model-description'])}</p><h2>${escape(t.ui.research)}</h2><div class="source-links"><a href="https://naturalhistory.si.edu/research/invertebrate-zoology/news-and-highlights/cowrie" target="_blank" rel="noopener noreferrer">Smithsonian · ${escape({de:'Schnecken und ihr Haus',fr:'Les escargots et leur coquille',en:'Snails and their shells'}[lang])}</a><a href="https://ocean.si.edu/ecosystems/shells-story" target="_blank" rel="noopener noreferrer">Smithsonian Ocean</a><a href="https://inpn.mnhn.fr/docs/communication/livretInpn/Livret-INPN-biodiversite-France-Mollusques-2023.pdf" target="_blank" rel="noopener noreferrer">MNHN</a></div><p class="sources-footer">${escape(t.ui.credits)}</p><div class="actions">${button(t.controls.back,'close-about')}</div>`;}

function updateSketchState(){const hasLine=sketchLines.some(line=>line.length),download=$('[data-action="download"]'),status=$('#sketch-status');if(download)download.disabled=!hasLine;if(status)status.textContent=hasLine?c().sketch.saved:'';}
document.addEventListener('pointerdown',event=>{if(event.target.id!=='card-drawing'||scene!=='ending'||!ready)return;event.preventDefault();sketchActive=true;event.target.setPointerCapture(event.pointerId);sketchLines.push([sketchPoint(event,event.target)]);updateDrawing();});
document.addEventListener('pointermove',event=>{if(!sketchActive||event.target.id!=='card-drawing')return;event.preventDefault();sketchLines.at(-1).push(sketchPoint(event,event.target));paintKeepsake(event.target,artImage('assets/scallop.png'),sketchLines);});
for(const type of ['pointerup','pointercancel'])document.addEventListener(type,()=>{sketchActive=false;});
function wrap(ctx,text,x,y,width,lineHeight){let line='',yy=y;for(const word of text.split(' ')){const test=line?`${line} ${word}`:word;if(ctx.measureText(test).width>width&&line){ctx.fillText(line,x,yy);yy+=lineHeight;line=word;}else line=test;}ctx.fillText(line,x,yy);return yy+lineHeight;}
async function downloadCard(){
  try{
    await document.fonts.ready;
    const canvas=document.createElement('canvas');canvas.width=1400;canvas.height=1800;const ctx=canvas.getContext('2d');
    ctx.fillStyle='#f2f7f5';ctx.fillRect(0,0,1400,1800);ctx.fillStyle='#153e55';ctx.font='66px "Della Respira"';ctx.fillText(c().ui.name,110,150);
    if(!sketchLines.some(line=>line.length))return;await artImage('assets/scallop.png').decode();
    const drawing=document.createElement('canvas');drawing.width=1160;drawing.height=800;paintKeepsake(drawing,artImage('assets/scallop.png'),sketchLines);ctx.drawImage(drawing,120,215);
    ctx.font='48px "Della Respira"';let yy=wrap(ctx,c().ending['keepsake-title'],110,1120,1160,69);ctx.font='42px "Josefin Sans"';yy=wrap(ctx,c().ending['card-line-1'],110,yy+60,1160,60);wrap(ctx,c().ending['card-line-2'],110,yy+15,1160,60);
    ctx.font='23px "Josefin Sans"';ctx.fillText(c().ending['card-note'],110,1610);ctx.fillText('SALONFORMAT',110,1670);ctx.fillText('salonformat.com',110,1715);
    const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('Empty export');
    const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`coquillages-${lang}.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);announce(c().ui.cardSaved);
  }catch{announce(c().controls['download-error']);const existing=$('#download-error');if(existing)existing.textContent=c().controls['download-error'];else{const p=document.createElement('p');p.id='download-error';p.className='feedback';p.setAttribute('role','alert');p.textContent=c().controls['download-error'];$('.scene-copy').append(p);}}
}
updateTrack();
const initialY=history.state?.journey===2&&Number.isFinite(history.state.y)?history.state.y:offsetFor(scene,0,innerHeight);
progress=scene==='about'?0:positionAt(initialY,viewportHeight).progress;lastY=initialY;history.replaceState(routeState(initialY),'',routeUrl(location.href,scene,lang));restoring=true;render(false);window.scrollTo({top:initialY,behavior:'instant'});requestAnimationFrame(()=>{restoring=false;});document.fonts.ready.then(updateDrawing);
